const LITERAL = "und\ten-Latn-US";
const SPAN = 18252;
/** One printable base-91 digit back to its value. */
const digit = (/** @type {string} */ s, /** @type {number} */ i) => {
  const c = s.charCodeAt(i);
  return (c > 92 ? c - 1 : c) - 35;
};
/** The 2-3 letter code a bitset slot stands for. */
const codeAt = (/** @type {number} */ slot) => {
  const pair = (slot / 27) | 0, third = slot % 27, A = 97;
  return third
    ? String.fromCharCode(A + ((pair / 26) | 0), A + (pair % 26), A + third - 1)
    : String.fromCharCode(A + ((pair / 26) | 0), A + (pair % 26));
};
/** @returns {{from: string, to: string}[]} */
export const decode = () => {
  const bits = Uint8Array.from(atob(KEYS), (c) => c.charCodeAt(0));
  /** @param {number} n */
  const pairAt = (n) => {
    const field = PAIRS.slice(n * 7, n * 7 + 7);
    return [field.slice(0, 4), field.charCodeAt(6) === 32 ? field.slice(4, 6) : field.slice(4)];
  };
  /** @param {string} stream @param {{ at: number }} cursor */
  const indexFrom = (stream, cursor) => {
    const first = digit(stream, cursor.at++);
    if (first !== 90) return first;
    return 90 + digit(stream, cursor.at++) * 91 + digit(stream, cursor.at++);
  };
  /** @type {{from: string, to: string}[]} */
  const simple = [];
  const walk = { at: 0 };
  for (let slot = 0; slot < SPAN; slot++) {
    if (!(((bits[slot >> 3] ?? 0) >> (slot & 7)) & 1)) continue;
    const from = codeAt(slot);
    const [script, region] = pairAt(indexFrom(VALUES, walk));
    simple.push({ from, to: `${from}-${script}-${region}` });
  }
  /** @type {{from: string, to: string}[]} */
  const rest = [];
  const other = { at: 0 };
  [BY_SCRIPT, BY_REGION, BY_BOTH].forEach((group, shape) => {
    if (!group) return;
    for (const entry of group.split(" ")) {
      const arrow = entry.indexOf(">");
      const fromLanguage = arrow < 0 ? entry : entry.slice(0, arrow);
      const toLanguage = arrow < 0 ? fromLanguage : entry.slice(arrow + 1);
      const [script, region] = pairAt(indexFrom(EXCEPTION_VALUES, other));
      const suffix = shape === 0 ? script : shape === 1 ? region : `${script}-${region}`;
      rest.push({ from: `${fromLanguage}-${suffix}`, to: `${toLanguage}-${script}-${region}` });
    }
  });
  for (const entry of LITERAL.split("\n")) {
    const tab = entry.indexOf("\t");
    rest.push({ from: entry.slice(0, tab), to: entry.slice(tab + 1) });
  }
  rest.sort((x, y) => (x.from < y.from ? -1 : 1));
  /** @type {{from: string, to: string}[]} */
  const out = [];
  const row = (/** @type {{from: string, to: string}[]} */ list, /** @type {number} */ i) =>
    /** @type {{from: string, to: string}} */ (list[i]);
  let a = 0, b = 0;
  while (a < simple.length && b < rest.length)
    out.push(row(simple, a).from < row(rest, b).from ? row(simple, a++) : row(rest, b++));
  while (a < simple.length) out.push(row(simple, a++));
  while (b < rest.length) out.push(row(rest, b++));
  return out;
};
